/**
 * @param {string} s
 * @param {number} k
 * @return {string}
 */
var digitSum = function(s, k) {
    while (s.length > k) {
        const stack = Array(Math.ceil(s.length / k)).fill(0);

        for (let i = 0; i < s.length; i++) {
            const pos = Math.floor(i / k);
            stack[pos] += Number(s[i]);
        }

        s = stack.join('');
    }

    return s;
};
